mapper.select:
SELECT p.post_id, p.board_id, p.author_id, p.title, p.content, p.view_count, p.like_count, p.comment_count, p.is_top, p.status, p.create_time, p.update_time, u.username AS author_username, u.nickname AS author_nickname FROM forum_post p LEFT JOIN sys_user u ON u.user_id = p.author_id
p.status = 1 AND p.board_id = #{boardId}
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY p.is_top DESC, p.create_time DESC LIMIT #{offset}, #{size}
